        self.rate = rate
        self.burst = burst
        self.buckets = {}

    def allow(self, key, now):
        if key not in self.buckets:
            self.buckets[key] = {
                'tokens': float(self.burst),
                'last_time': now
            }

        bucket = self.buckets[key]
        if now < bucket['last_time']:
            raise ValueError("Time going backwards")

        elapsed = now - bucket['last_time']
        refill = elapsed * self.rate

        new_tokens = min(float(self.burst), bucket['tokens'] + refill)

